using System.Globalization;
using System.Numerics;
using System.Text.Json;
using ValveKeyValue;
using ValveResourceFormat;
using ValveResourceFormat.Blocks;
using ValveResourceFormat.ResourceTypes;
using ValveResourceFormat.ResourceTypes.ModelAnimation;

// Bake only Fluid Frenzy's extra head bones into existing hero clips. Never
// replace host segments, activities, events, frame counts, or shared bone tracks.
internal static class MorphlingFishChannels {
 private sealed record Request(string Input,string Head,string Output,string Report);
 static string S(KVObject v)=>v.ToString(CultureInfo.InvariantCulture);
 static KVObject A(IEnumerable<KVObject> values)=>KVObject.Array(values);
 static KVObject Row(params(string,KVObject)[] fields){var r=KVObject.Collection();foreach(var(k,v)in fields)r[k]=v;return r;}
 static BinaryKV3 Read(Resource r,byte[] bytes,Block b){var kv=new BinaryKV3(b.Type){Resource=r,Offset=b.Offset,Size=b.Size};using var reader=new BinaryReader(new MemoryStream(bytes));reader.BaseStream.Position=b.Offset;kv.Read(reader);return kv;}
 internal static byte[] Segment(int decoder,int dimensions,short[] elements,Action<BinaryWriter> write){using var stream=new MemoryStream();using var w=new BinaryWriter(stream);w.Write((short)decoder);w.Write((short)dimensions);w.Write((short)elements.Length);w.Write((ushort)0);foreach(var e in elements)w.Write(e);write(w);var bytes=stream.ToArray();if(bytes.Length>ushort.MaxValue)throw new InvalidDataException("Animation segment too large");BitConverter.GetBytes((ushort)bytes.Length).CopyTo(bytes,6);return bytes;}
 static float Error(FrameBone a,FrameBone b)=>Math.Max(Vector3.Distance(a.Position,b.Position),Math.Max(Math.Abs(a.Scale-b.Scale),1-Math.Abs(Quaternion.Dot(a.Angle,b.Angle))));
 public static void Run(string manifest){
  var q=JsonSerializer.Deserialize<Request>(File.ReadAllText(manifest),new JsonSerializerOptions{PropertyNameCaseInsensitive=true})??throw new InvalidDataException("Empty fish request");
  using var host=new Resource{FileName=q.Input};host.Read(q.Input);using var head=new Resource{FileName=q.Head};head.Read(q.Head);var model=host.DataBlock as Model??throw new InvalidDataException("Expected host model");var donor=head.DataBlock as Model??throw new InvalidDataException("Expected head model");
  var original=File.ReadAllBytes(q.Input);var headBytes=File.ReadAllBytes(q.Head);var ab=host.Blocks.Single(b=>b.Type==BlockType.ANIM);var gb=host.Blocks.Single(b=>b.Type==BlockType.AGRP);var anim=Read(host,original,ab);var group=Read(host,original,gb);var key=group.Data.Root["m_decodeKey"];
  var headGroup=Read(head,headBytes,head.Blocks.Single(b=>b.Type==BlockType.AGRP));var sourceKey=headGroup.Data.Root["m_decodeKey"];var sourceBones=sourceKey["m_boneArray"].Values.ToArray();var keyBones=key["m_boneArray"].Values.ToList();var keyNames=keyBones.Select(b=>S(b["m_name"])).ToList();var originalNames=keyNames.ToArray();
  var extra=sourceBones.Where(b=>!keyNames.Contains(S(b["m_name"]))).ToArray();if(extra.Length==0||extra.Any(b=>!S(b["m_name"]).StartsWith("shark_")&&!S(b["m_name"]).StartsWith("fin_")))throw new InvalidDataException("Expected only Fluid Frenzy fish/fin animation bones");
  var names=extra.Select(b=>S(b["m_name"])).ToArray();var modelNames=model.Skeleton.Bones.Select(b=>b.Name).ToArray();if(names.Any(n=>!modelNames.Contains(n)))throw new InvalidDataException("Fish geometry bones missing from merged model");
  foreach(var b in extra){keyNames.Add(S(b["m_name"]));keyBones.Add(b);}foreach(var b in extra){var parent=b["m_parent"].ToInt32(null);if(parent>=0)b["m_parent"]=new KVObject(keyNames.IndexOf(S(sourceBones[parent]["m_name"])));}
  key["m_boneArray"]=A(keyBones);
  var sk=model.Data["m_modelSkeleton"];var sourceSk=donor.Data["m_modelSkeleton"];var sourceModelNames=donor.Skeleton.Bones.Select(b=>b.Name).ToArray();foreach(var name in names.Where(n=>n.StartsWith("shark_"))){var from=Array.IndexOf(sourceModelNames,name);if(sourceSk["m_nParent"][from].ToInt32(null)>=0)continue;var to=Array.IndexOf(modelNames,name);foreach(var field in new[]{"m_nParent","m_bonePosParent","m_boneRotParent","m_boneScaleParent"}){var rows=sk[field].Values.ToArray();rows[to]=sourceSk[field][from];sk[field]=A(rows);}}
  var sourceClip=donor.GetEmbeddedAnimations().Single(a=>a.Name=="morph_tritons_revenge_back_idle");var sourceCache=new AnimationFrameCache(donor.Skeleton,donor.FlexControllers);var sourceIndices=names.Select(n=>Array.IndexOf(sourceModelNames,n)).ToArray();
  var channels=key["m_dataChannelArray"].Values.ToList();var element=key["m_nChannelElements"].ToInt32(null);var channelIds=new int[3];var ids=new short[3][];var masks=new uint[3];var types=new[]{"Position","Angle","Scale"};var dims=new[]{3,4,1};
  for(int c=0;c<3;c++){channelIds[c]=channels.Count;var template=sourceKey["m_dataChannelArray"].Values.Single(v=>S(v["m_szVariableName"])==types[c]);ids[c]=Enumerable.Range(element,names.Length).Select(i=>checked((short)i)).ToArray();element+=names.Length;var oldNames=template["m_szElementNameArray"].Values.Select(S).ToArray();var flags=names.Select(n=>template["m_nElementMaskArray"][Array.IndexOf(oldNames,n)]).ToArray();masks[c]=flags.Aggregate(0u,(a,v)=>a|unchecked((uint)v.ToInt64(null)));var copy=Row(template.Select(p=>(p.Key,p.Value)).ToArray());copy["m_szElementNameArray"]=A(names.Select(n=>new KVObject(n)));copy["m_nElementIndexArray"]=A(ids[c].Select(i=>new KVObject((int)i)));copy["m_nElementMaskArray"]=A(flags);channels.Add(copy);}
  key["m_nChannelElements"]=new KVObject(element);key["m_dataChannelArray"]=A(channels);var decoderNames=anim.Data.Root["m_decoderArray"].Values.Select(v=>S(v["m_szName"])).ToArray();var decoderIds=new[]{Array.IndexOf(decoderNames,"CCompressedFullVector3"),Array.IndexOf(decoderNames,"CCompressedFullQuaternion"),Array.IndexOf(decoderNames,"CCompressedFullFloat")};if(decoderIds.Any(i=>i<0))throw new InvalidDataException("Missing full precision decoders");
  var segments=anim.Data.Root["m_segmentArray"].Values.ToList();var oldSegmentCount=segments.Count;var clips=0;var samples=0;var uniqueFrame=anim.Data.Root["m_nMaxUniqueFrameIndex"].ToInt32(null)+1;
  foreach(var clip in anim.Data.Root["m_animArray"].Values){var fps=clip["fps"].ToSingle(null);if(!float.IsFinite(fps)||fps<=0)throw new InvalidDataException("Invalid host FPS");var data=clip["m_pData"];foreach(var block in data["m_frameblockArray"].Values){var start=block["m_nStartFrame"].ToInt32(null);var end=block["m_nEndFrame"].ToInt32(null);if(start<0||end<start||end-start>1024)throw new InvalidDataException("Unsupported frame block");var frames=Enumerable.Range(start,end-start+1).Select(i=>{var f=sourceCache.GetInterpolatedFrame(sourceClip,i/fps);return sourceIndices.Select(j=>f.Bones[j]).ToArray();}).ToArray();var indexes=block["m_segmentIndexArray"].Values.ToList();
   for(int c=0;c<3;c++){var channel=c;var blob=Segment(decoderIds[c],dims[c],ids[c],w=>{foreach(var frame in frames)foreach(var bone in frame){if(channel==0){w.Write(bone.Position.X);w.Write(bone.Position.Y);w.Write(bone.Position.Z);}else if(channel==1){w.Write(bone.Angle.X);w.Write(bone.Angle.Y);w.Write(bone.Angle.Z);w.Write(bone.Angle.W);}else w.Write(bone.Scale);}});indexes.Add(new KVObject(segments.Count));segments.Add(Row(("m_nUniqueFrameIndex",new KVObject(uniqueFrame)),("m_nLocalElementMasks",new KVObject(masks[c])),("m_nLocalChannel",new KVObject(channelIds[c])),("m_container",KVObject.Blob(blob))));}block["m_segmentIndexArray"]=A(indexes);samples+=frames.Length;uniqueFrame+=frames.Length;}
   var usage=data["m_usageDifferences"];foreach(var field in new[]{"m_bHasRotationBitArray","m_bHasMovementBitArray"}){var old=usage[field].Values.Select(v=>(byte)v.ToInt32(null)).ToArray();var bits=new byte[Math.Max(old.Length,(keyBones.Count+7)/8)];old.CopyTo(bits,0);for(int i=originalNames.Length;i<keyBones.Count;i++)bits[i/8]|=(byte)(1<<(i%8));usage[field]=A(bits.Select(v=>new KVObject((int)v)));}
   // Bounds arrays are indexed by decode-key bones, unlike the geometry skeleton.
   foreach(var field in new[]{"m_vecBoneWorldMin","m_vecBoneWorldMax"})if(clip.TryGetValue(field,out var bounds)&&bounds.Count==originalNames.Length){var value=field.EndsWith("Min")?-512f:512f;clip[field]=A(bounds.Values.Concat(names.Select(_=>A(new[]{new KVObject(value),new KVObject(value),new KVObject(value)}))));}
   clips++;
  }
  anim.Data.Root["m_segmentArray"]=A(segments);anim.Data.Root["m_nMaxUniqueFrameIndex"]=new KVObject(uniqueFrame);var raw=new Dictionary<object,byte[]>{{ab,HeroActivityRules.SerializeActivity(anim,original[(int)ab.Offset])},{gb,HeroActivityRules.SerializeActivity(group,original[(int)gb.Offset])}};
  using(var output=File.Create(q.Output))Program.SerializePatchedResource(host,original,output,true,preserveMetadata:true,rawBlocks:raw);
  // Read the actual serialized file and decode every frame. Equality checks
  // cover the original host bones as well as the newly baked head channels.
  using var check=new Resource{FileName=q.Output};check.Read(q.Output);var result=(Model)check.DataBlock!;var oldClips=model.GetEmbeddedAnimations().ToDictionary(a=>a.Name);var newClips=result.GetEmbeddedAnimations().ToDictionary(a=>a.Name);var oldCache=new AnimationFrameCache(model.Skeleton,model.FlexControllers);var newCache=new AnimationFrameCache(result.Skeleton,result.FlexControllers);var targetNames=result.Skeleton.Bones.Select(b=>b.Name).ToArray();var oldModelNames=model.Skeleton.Bones.Select(b=>b.Name).ToArray();float maxFish=0,maxHost=0,maxFishTravel=0;var firstFish=new Dictionary<string,Vector3>();int verified=0;
  foreach(var(name,old)in oldClips){var next=newClips[name];if(old.FrameCount!=next.FrameCount||old.Fps!=next.Fps)throw new InvalidDataException("Host timing changed");for(int i=0;i<old.FrameCount;i++){var before=oldCache.GetFrame(old,i);var after=newCache.GetFrame(next,i);var expected=sourceCache.GetInterpolatedFrame(sourceClip,i/old.Fps);foreach(var bone in originalNames){var a=Array.IndexOf(oldModelNames,bone);var b=Array.IndexOf(targetNames,bone);maxHost=Math.Max(maxHost,Error(before.Bones[a],after.Bones[b]));}for(int j=0;j<names.Length;j++){var actual=after.Bones[Array.IndexOf(targetNames,names[j])];maxFish=Math.Max(maxFish,Error(expected.Bones[sourceIndices[j]],actual));if(names[j].StartsWith("shark_")){if(!firstFish.ContainsKey(names[j]))firstFish[names[j]]=actual.Position;maxFishTravel=Math.Max(maxFishTravel,Vector3.Distance(firstFish[names[j]],actual.Position));}}verified++;}}
  if(maxFishTravel<1)throw new InvalidDataException("Fish sequence contains no measurable movement");if(maxHost>0.0001f||maxFish>0.0001f)throw new InvalidDataException($"Fish channel roundtrip mismatch: fish={maxFish}, host={maxHost}");File.WriteAllText(q.Report,JsonSerializer.Serialize(new{version=1,bones=names,clips,oldSegmentCount,newSegmentCount=segments.Count,samples,verifiedFrames=verified,maxFishError=maxFish,maxHostError=maxHost,maxFishTravel}));Console.WriteLine($"[OK] Direct fish channels: {clips} clips, {verified} verified frames");
 }
}
